SELECT 
FROM share_summary_run
WHERE task_id = #{taskId}
  AND trigger_type = 'SCHEDULED'
  AND window_start = #{windowStart}
  AND window_end = #{windowEnd}
ORDER BY id DESC
LIMIT 1

SELECT 
FROM share_summary_run
WHERE 
ORDER BY started_at DESC, id DESC
LIMIT #{limit}
OFFSET #{offset}
